"""Generate analytical tables and source documentation from the published inputs."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
bundle=json.loads((ROOT/'results/model_results.json').read_text(encoding='utf-8'))
sources=json.loads((ROOT/'data/sources.json').read_text(encoding='utf-8'))
results=bundle['results']
def effect(s,h):return next(r for r in results if r['scenario']==s and r['hypothesis']==h)
def pp(x):return f'{x:+.4f}'.replace('.',',')
names=[('H1','Поиск/фильтры Корзины'),('H2','Сохранение выбранного SKU'),('H3','Купить сейчас / На потом'),('H4','Сквозной поиск'),('H5','Покупка из Избранного'),('H6.1','Сравнение'),('H6.2','Фильтрация по условиям'),('H6.3','Шорт-лист')]
lines=['# Результаты сценарного моделирования Ozon','',
       'Дата публикационной проверки: 29.10.2026. Обновлена существующая модель; 26 сценариев × 8 самостоятельных альтернатив. Все эффекты ниже условные, в процентных пунктах глобальной дневной CR. Выбор сетки не задаёт вероятности сценариев.','',
       '| H | Решение | Исходная модель | Taobao, CR0=20,1% | База CR0=15% | Осторожный | Благоприятный |',
       '|---|---|---:|---:|---:|---:|---:|']
for h,name in names:
    values=[pp(effect(s,h)['delta_pp']) for s in ['original','taobao_control_201','taobao_calibrated','cautious','favorable']]
    lines.append('| '+' | '.join([h,name,*values])+' |')
