(ROOT/'docs/findings.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
lines=['# Проверка публичных источников','',
       'Проверено 29.10.2026. Доступность полного текста и подтверждение конкретной цифры отмечены раздельно. При блокировке страницы использован индекс страницы первичного издателя; это не полная проверка методов исследования.','']
for s in sources:
    link=s['title'] if s['url'].startswith('local:') else '['+s['title']+']('+s['url']+')'
    lines.extend(['## '+link,'','Статус: '+s['status']+'.','',s['facts']+'.','',
                  'Использование: '+s['use']+'.','', 'Предел переноса: '+s['limitation']+'.',''])
